/**
 * Small format registry used by render adapters and applications.
 * Sekai64 does not assume that every model or media format belongs in core.
 */
export class AssetLoaderRegistry {
    entries = [];
    register(registration) {
        const type = registration.type.trim().toLowerCase();
        const formats = new Set(registration.formats.map(normalizeFormat).filter(Boolean));
        if (!type)
            throw new Error('Asset loaders require a non-empty type.');
        if (formats.size === 0)
            throw new Error(`Asset loader "${type}" requires at least one format.`);
        for (const format of formats) {
            if (this.resolve(type, format))
                throw new Error(`An asset loader is already registered for ${type}/${format}.`);
        }
        const normalized = { ...registration, type, formats: [...formats] };
        const entry = { registration: normalized, formats };
        this.entries.push(entry);
        return () => {
            const index = this.entries.indexOf(entry);
            if (index >= 0)
                this.entries.splice(index, 1);
        };
    }
    resolve(type, format) {
        const normalizedType = type.trim().toLowerCase();
        const normalizedFormat = normalizeFormat(format);
        return this.entries.find((entry) => entry.registration.type === normalizedType && entry.formats.has(normalizedFormat))?.registration;
    }
    supports(type, format) {
        return this.resolve(type, format) !== undefined;
    }
    formats(type) {
        const normalizedType = type.trim().toLowerCase();
        return [...new Set(this.entries
                .filter((entry) => entry.registration.type === normalizedType)
                .flatMap((entry) => [...entry.formats]))].sort();
    }
    capabilities() {
        const result = {};
        for (const entry of this.entries)
            result[entry.registration.type] = this.formats(entry.registration.type);
        return result;
    }
    async load(request) {
        const loader = this.resolve(request.type, request.format);
        if (!loader)
            throw new Error(`No asset loader is registered for ${request.type}/${request.format}.`);
        return loader.load({ ...request, type: request.type.toLowerCase(), format: normalizeFormat(request.format) });
    }
    dispose() {
        const disposed = new Set();
        for (const entry of this.entries) {
            if (disposed.has(entry.registration))
                continue;
            disposed.add(entry.registration);
            entry.registration.dispose?.();
        }
        this.entries.length = 0;
    }
}
function normalizeFormat(format) {
    return format.trim().toLowerCase().replace(/^\./, '');
}